insert into public.daily_quests (rotation_index, title_de, title_en, desc_de, desc_en, emoji) values
  (0, 'Übersehenes Detail', 'Overlooked Detail', 'Zeig etwas, das die meisten Leute übersehen.', 'Show something that most people overlook.', '👀'),
